use vstd::prelude::*;

verus! {

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Interval {
    pub min: i32,
    pub max: i32,
}

impl Interval {
    pub open spec fn valid(self) -> bool {
        self.min < self.max
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ChebyshevPoly {
    pub coef: Vec<i32>,
    pub domain: Interval,
    pub window: Interval,
}

pub fn chebyshev(coef: Vec<i8>) -> (res: ChebyshevPoly)
    requires
        coef.len() > 0,
    ensures
        res.domain.min == -1,
        res.domain.max == 1,
        res.window.min == -1,
        res.window.max == 1,
        res.domain.valid(),
        res.window.valid(),
        res.coef.len() == coef.len(),
        // Elementwise cast i8 -> i32 is preserved
        forall|i: int|
            0 <= i < coef.len() ==> res.coef[i] == coef[i] as i32,
{
    assert!(!coef.is_empty(), "coef must be non-empty");

    let coef_i32: Vec<i32> = coef.into_iter().map(|c| c as i32).collect();

    let domain = Interval { min: -1, max: 1 };
    let window = Interval { min: -1, max: 1 };

    // Ensures returned intervals are valid as required.
    debug_assert!(domain.min < domain.max);
    debug_assert!(window.min < window.max);

    ChebyshevPoly { coef: coef_i32, domain, window }
}

} // verus!

